-- Convert standard table to hypertable
CREATE TABLE energy_readings (time TIMESTAMPTZ NOT NULL, meter_id TEXT, usage DOUBLE PRECISION) WITH (tsdb.hypertable);

-- Create continuous aggregate for hourly stats
CREATE MATERIALIZED VIEW hourly_usage WITH (timescaledb.continuous) AS 
SELECT time_bucket('1 hour', time) AS hour, meter_id, AVG(usage) FROM energy_readings GROUP BY hour, meter_id;
